Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

$Template = ".github/halleus-preflight/a2a-harness.ps1"
$Generated = Join-Path $env:RUNNER_TEMP "a2a-harness-candidate4.generated.ps1"
$Utf8 = New-Object System.Text.UTF8Encoding($false)

function Replace-ExactlyOnce {
    param([string]$Text,[string]$Old,[string]$New,[string]$Name)
    $First = $Text.IndexOf($Old, [StringComparison]::Ordinal)
    if ($First -lt 0) { throw "ANCHOR_NOT_FOUND=$Name" }
    $Second = $Text.IndexOf($Old, $First + $Old.Length, [StringComparison]::Ordinal)
    if ($Second -ge 0) { throw "ANCHOR_NOT_UNIQUE=$Name" }
    return $Text.Substring(0,$First) + $New + $Text.Substring($First + $Old.Length)
}

$Harness = [IO.File]::ReadAllText($Template, $Utf8)
$Harness = Replace-ExactlyOnce -Text $Harness -Old '$CandidateRunnerSha = "c1f76dc626a401f65817a4b7fdfeea995f1acc99b0d4df3a918100608912acf2"' -New '$CandidateRunnerSha = "38db15ea76ff14c301d27a99c6a86f7201b0304e30ac3374e7a45944769b0c5c"' -Name "candidate4-sha"

$PatchBlock = $Utf8.GetString([Convert]::FromBase64String(""))
$WriteAnchor = "[IO.File]::WriteAllText(`$Runner, `$Content, `$Utf8)"
$Harness = Replace-ExactlyOnce -Text $Harness -Old $WriteAnchor -New ($PatchBlock + $WriteAnchor) -Name "insert-transform-patch"
[IO.File]::WriteAllText($Generated, $Harness, $Utf8)

$Tokens = $null
$Errors = $null
[System.Management.Automation.Language.Parser]::ParseFile($Generated, [ref]$Tokens, [ref]$Errors) | Out-Null
if ($Errors.Count -gt 0) { $Errors | ForEach-Object { Write-Host $_.Message }; throw "GENERATED_HARNESS_PARSE_FAILED" }
Write-Host "GENERATED_HARNESS_PARSE=PASS"
& powershell.exe -NoProfile -ExecutionPolicy Bypass -File $Generated
if ($LASTEXITCODE -ne 0) { throw "GENERATED_HARNESS_FAILED=$LASTEXITCODE" }
